// Repository-owned synthetic VP8 fixture captured once from a moving two-color
// 1280x720 canvas, then frozen and digest-pinned here. The benchmark consumes
// these bytes directly so fixture setup never starts browser capture APIs.
const VIDEO_PREVIEW_BENCHMARK_WEBM_BASE64 = '';

export const videoPreviewBenchmarkMedia = Object.freeze({
	id: 'video-preview-12fx-720p-v1',
	generatorRevision: 1,
	display: Object.freeze({ width: 1_280, height: 720 }),
	frameRate: 30,
	frameCount: 180,
	file: Object.freeze({
		name: 'video-preview-benchmark.webm',
		mimeType: 'video/webm',
		buffer: Buffer.from(VIDEO_PREVIEW_BENCHMARK_WEBM_BASE64, 'base64'),
	}),
	byteLength: 109277,
	sourceSha256: 'f1319d3549943c190e5eb3f86b63fd2afb644bd49b32e3f257699b450271bc8c',
});

export function createVideoPreviewBenchmarkFixture(name = videoPreviewBenchmarkMedia.file.name) {
	const fileName = String(name || '').trim();
	if (!fileName) throw new TypeError('A video preview benchmark fixture name is required.');
	return {
		name: fileName,
		mimeType: videoPreviewBenchmarkMedia.file.mimeType,
		buffer: Buffer.from(videoPreviewBenchmarkMedia.file.buffer),
	};
}
